──────────────────────────────────────────────────────────────────────────── */

/* ---------- shared geometry / materials ---------- */
const CYLG  = new THREE.CylinderGeometry(1, 1, 1, 12);
const CONEG = new THREE.ConeGeometry(1, 1, 16);
const SPHG  = new THREE.SphereGeometry(1, 20, 14);
const PLNG  = new THREE.PlaneGeometry(1, 1);
const UPY   = new THREE.Vector3(0, 1, 0);

function mkMat(c, o) {
  return new THREE.MeshBasicMaterial({
    color: c, transparent: true, opacity: (o === undefined ? 1 : o),
    side: THREE.DoubleSide, depthWrite: false
  });
}
const M_BLACK = mkMat(0x000000), M_GRAY = mkMat(0x808A94), M_DGRAY = mkMat(0x5A6468),
      M_VP = mkMat(0xDDE4E6, 0.55), M_GRN = mkMat(0x1FBF1F),
      M_SGREEN = mkMat(0xA9E8A0, 0.88), M_YEL = mkMat(0xF2C21E), M_RED = mkMat(0xEE2027),
      M_CYAN = mkMat(0x29C5F6), M_HL = mkMat(0x29C5F6, 0.45),
      M_HIT = mkMat(0xffffff, 0.0);
const M_OUT = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.BackSide, transparent: true, depthWrite: false });
const M_GRID = new THREE.LineBasicMaterial({ color: 0x8A9099, transparent: true, depthWrite: false });
const M_PIX  = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, side: THREE.DoubleSide, depthWrite: false });

/* ---------- primitive builders ---------- */
function placeCyl(m, a, b, r) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-6);
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.scale.set(r, len, r);
  m.quaternion.setFromUnitVectors(UPY, dir.clone().normalize());
}
function mkCyl(a, b, r, mat, order) {
  const m = new THREE.Mesh(CYLG, mat); placeCyl(m, a, b, r); m.renderOrder = order || 10; return m;
}
function mkArrow(a, b, r, mat, order, headLen, headR) {
  headLen = headLen || 0.26; headR = headR || 0.085;
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(b, a).normalize();
  const tail = b.clone().addScaledVector(dir, -headLen * 0.9);
  g.add(mkCyl(a, tail, r, mat, order));
  const cone = new THREE.Mesh(CONEG, mat);
  cone.scale.set(headR, headLen, headR);
  cone.position.copy(b).addScaledVector(dir, -headLen / 2);
  cone.quaternion.setFromUnitVectors(UPY, dir);
  cone.renderOrder = order || 10;
  g.add(cone);
  return g;
}
function mkDArrow(a, b, r, mat, order, headLen, headR) {
  const g = new THREE.Group();
  g.add(mkArrow(a, b, r, mat, order, headLen, headR));
  g.add(mkArrow(b, a, r, mat, order, headLen, headR));
  return g;
}
function mkDot(p, r, mat, order, outline) {
  const g = new THREE.Group();
  if (outline) {
    const o = new THREE.Mesh(SPHG, M_OUT); o.scale.setScalar(r * 1.35); o.renderOrder = (order || 13);
    g.add(o);
  }
  const m = new THREE.Mesh(SPHG, mat); m.scale.setScalar(r); m.renderOrder = (order || 13) + 1;
  g.add(m); g.position.copy(p);
  return g;
}
function mkQuad(wid, hei, mat, order) {
  const m = new THREE.Mesh(PLNG, mat); m.scale.set(wid, hei, 1); m.renderOrder = order || 5; return m;
}
function clearGroup(g) {
  while (g.children.length) {
