  const ax0 = new THREE.Vector3(-0.45 * w, 0, f), ax1 = new THREE.Vector3(0.30 * w, 0, f);
  const ay0 = new THREE.Vector3(0, -0.42 * h, f), ay1 = new THREE.Vector3(0, 0.45 * h, f);
  gDyn.add(mkArrow(ax0, ax1, 0.02, M_GRN, 6, 0.2, 0.065));
  gDyn.add(mkArrow(ay0, ay1, 0.02, M_GRN, 6, 0.2, 0.065));
  const a = 0.15;
  gDyn.add(mkCyl(new THREE.Vector3(a, 0, f), new THREE.Vector3(a, a, f), 0.012, M_GRN, 6));
  gDyn.add(mkCyl(new THREE.Vector3(0, a, f), new THREE.Vector3(a, a, f), 0.012, M_GRN, 6));

  SEN.fY = fY; SEN.ax1 = ax1; SEN.ay1 = ay1;
  layout();
  updateProjection();
}

/* ---------- projection + readout ---------- */
function updateProjection() {
  const f = S.f, P = S.P;
  const Z = Math.max(P.z, 0.2);
  const xv = f * P.x / Z, yv = f * P.y / Z;
  gP.position.copy(P); pHit.position.copy(P);
  gPv.position.set(xv, yv, f);
  gPs.position.set(-xv, -yv, -f);
  drawDash(P, gPs.position, 0.022, 0.13, 0.09);

  const { sx, sy, x0, y0, N, M, ox, oy } = SEN;
  const xs = -xv, ys = -yv;
  const nc = xs / sx + ox, mc = oy - ys / sy;
  const ni = Math.floor(nc), mi = Math.floor(mc);
  if (ni >= 0 && ni < N && mi >= 0 && mi < M) {
    hlQuad.visible = true;
    hlQuad.scale.set(sx, sy, 1);
    hlQuad.position.set(x0 + (ni + 0.5) * sx, y0 + (M - 1 - mi + 0.5) * sy, -f + 0.0);
  } else hlQuad.visible = false;

  updateReadout(xv, yv, nc, mc, ni, mi);
}

function fmt(v, d) { d = (d === undefined ? 2 : d); return (Math.abs(v) < 5e-4 ? 0 : v).toFixed(d); }
function updateReadout(xv, yv, nc, mc, ni, mi) {
  const { sx, sy, N, M, ox, oy, w, h } = SEN, f = S.f, P = S.P;
  const fx = f / sx, fy = f / sy;
  let txt = 'P (camera) = (' + fmt(P.x) + ', ' + fmt(P.y) + ', ' + fmt(P.z) + ')\n';
  if (S.mode === 0) {
    txt += 'x = f·X/Z = ' + fmt(xv, 3) + '\n';
    txt += 'y = f·Y/Z = ' + fmt(yv, 3) + '\n';
    txt += '(virtual plane, upright)';
  } else if (S.mode === 1) {
    txt += 'sensor hit, from principal pt:\n';
    txt += '  xs = −x = ' + fmt(-xv * 10, 2) + ' mm\n';
    txt += '  ys = −y = ' + fmt(-yv * 10, 2) + ' mm\n';
    txt += 'sensor ' + fmt(w * 10, 1) + ' × ' + fmt(h * 10, 1) + ' mm\n';
    txt += 'pixel ' + fmt(sx * 10, 3) + ' × ' + fmt(sy * 10, 3) + ' mm';
  } else {
    txt += 'n = xs/s_x + ox = ' + fmt(nc) + '\n';
    txt += 'm = oy − ys/s_y = ' + fmt(mc) + '\n';
    txt += 'snapped pixel  (n, m) = (' + ni + ', ' + mi + ')\n';
    txt += 'principal pt (ox, oy) = (' + fmt(ox, 1) + ', ' + fmt(oy, 1) + ')';
  }
  txt += '\n\nK = [' + fmt(fx, 1).padStart(6) + '    0  ' + fmt(ox, 1).padStart(5) + ' ]\n';
  txt += '    [    0  ' + fmt(fy, 1).padStart(6) + '  ' + fmt(oy, 1).padStart(5) + ' ]\n';
  txt += '    [    0       0    1.0 ]';
  document.getElementById('readout').textContent = txt;
}

/* ---------- first build & camera ---------- */
rebuildAll();
setCameraView({ projection: 'orthographic', azimuthDeg: 160, elevationDeg: 18, rollDeg: 0, heightFraction: 0.7 });

/* ---------- labels ---------- */
const L = {};
function lab(html, opts) {
  opts = opts || {};
  const e = addLabel(html, new THREE.Vector3(), opts);
  e.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  if (opts.rot) e.div.innerHTML = '<span style="display:inline-block;transform:rotate(' + opts.rot + 'deg)">' + html + '</span>';
  return e;
}
L.imgplane = lab('Image plane / sensor', { fontSize: '15px' });
L.npx      = lab('<i>N</i> pixels', { fontSize: '14px', rot: -40 });
L.mpx      = lab('<i>M</i> pixels', { fontSize: '14px', rot: -70 });
L.w        = lab('<i>w</i>', { fontSize: '16px' });
L.f        = lab('<i>f</i>', { fontSize: '17px' });
L.vplane   = lab('Virtual image plane', { fontSize: '14px', rot: -40 });
L.xg       = lab('<i>x</i>', { fontSize: '17px', color: '#0f9b0f' });
L.yg       = lab('<i>y</i>', { fontSize: '17px', color: '#0f9b0f' });
L.P        = lab('<b>P</b>', { fontSize: '17px' });
L.cc       = lab('Camera<br>center', { fontSize: '15px' });
L.opt      = lab('Optical /<br>principal axis', { fontSize: '15px' });
L.Xc       = lab('X<sub>c</sub>', { fontSize: '19px' });
L.Yc       = lab('Y<sub>c</sub>', { fontSize: '19px' });
L.Zc       = lab('Z<sub>c</sub>', { fontSize: '19px' });
L.cc.pos.set(0, -1.45, -1.25);
L.opt.pos.set(0, 1.15, 7.9);
L.Xc.pos.set(2.55, 0.18, 0); L.Xc.offset = [-6, -12];
L.Yc.pos.set(0, 3.45, 0);    L.Yc.offset = [18, -4];
L.Zc.pos.set(0, -0.45, 8.6);

function layout() {
  if (!L.f) return;
  const w = SEN.w, h = SEN.h, f = SEN.f, z = -f;
  L.imgplane.pos.set(-w * 0.55, h * 0.5 + 0.7, z);
  L.npx.pos.set(-w * 0.22, h * 0.5 + 0.18, z);
  L.mpx.pos.set(-w * 0.5 - 0.16, -h * 0.2, z);
  L.w.pos.set(-0.28, SEN.fY + 0.32, z);
  L.f.pos.set(0, SEN.fY - 0.34, -f / 2);
  L.vplane.pos.set(-w * 0.26, -h * 0.5 - 0.14, f);
  L.xg.pos.copy(SEN.ax1).add(new THREE.Vector3(0.1, 0.16, 0));
  L.yg.pos.copy(SEN.ay1).add(new THREE.Vector3(-0.18, 0.12, 0));
  L.P.pos.copy(S.P).add(new THREE.Vector3(0, 0.3, 0)); L.P.offset = [-14, -4];
}
layout();

/* ---------- drag P ---------- */
const dragRC = new THREE.Raycaster();
const dragPt = new THREE.Vector2();
const dragPlane = new THREE.Plane();
const hitV = new THREE.Vector3();
let dragging = false;
function setPtr(e) {
  const r = canvas.getBoundingClientRect();
  dragPt.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  dragPt.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
window.addEventListener('pointerdown', (e) => {
  if (e.target !== canvas) return;
  setPtr(e); dragRC.setFromCamera(dragPt, camera);
  if (dragRC.intersectObject(pHit, false).length) {
    dragging = true; controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    e.stopPropagation(); e.preventDefault();
  }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setPtr(e); dragRC.setFromCamera(dragPt, camera);
  const depthMode = document.getElementById('chkZ').checked;
  if (depthMode) dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 1, 0), S.P);
  else dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 0, 1), S.P);
  if (dragRC.ray.intersectPlane(dragPlane, hitV)) {
    if (depthMode) S.P.z = THREE.MathUtils.clamp(hitV.z, 3, 9);
    else {
      S.P.x = THREE.MathUtils.clamp(hitV.x, -1.8, 1.8);
      S.P.y = THREE.MathUtils.clamp(hitV.y, -1.4, 1.4);
    }
    layout(); updateProjection();
  }
  e.preventDefault();
}, true);
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'default'; }
});

/* ---------- UI wiring ---------- */
const elF = document.getElementById('sF'), elW = document.getElementById('sW'), elN = document.getElementById('sN');
function syncSliderText() {
  document.getElementById('vF').textContent = S.f.toFixed(2);
  document.getElementById('vW').textContent = S.w.toFixed(2);
  document.getElementById('vN').textContent = Math.round(S.N);
  document.getElementById('vM').textContent = Math.max(3, Math.round(Math.round(S.N) * 0.75));
}
elF.addEventListener('input', () => { tween = null; S.f = parseFloat(elF.value); syncSliderText(); rebuildAll(); });
elW.addEventListener('input', () => { tween = null; S.w = parseFloat(elW.value); syncSliderText(); rebuildAll(); });
elN.addEventListener('input', () => { tween = null; S.N = parseFloat(elN.value); syncSliderText(); rebuildAll(); });

function setMode(i) {
  S.mode = i;
  for (let k = 0; k < 3; k++) document.getElementById('rm' + k).classList.toggle('active', k === i);
  updateProjection();
}
for (let k = 0; k < 3; k++) document.getElementById('rm' + k).addEventListener('click', () => setMode(k));

/* ---------- demo steps ---------- */
const STEPS = [
  { t: 'The pinhole ray', n: 'A single dashed ray leaves scene point P, passes exactly through the camera center, and strikes the sensor behind it. Where it crosses the virtual image plane at distance f is the upright image; on the real sensor the same ray lands inverted.', s: { f: 2, w: 2.4, N: 16, mode: 0 } },
  { t: 'Longer focal length', n: 'Pushing f out to 3.2 moves both image planes away from the pinhole. The projected point swings further from the optical axis and the field of view narrows — the classic zoom-in tradeoff.', s: { f: 3.2, w: 2.4, N: 16, mode: 0 } },
  { t: 'Sensor-centred millimetres', n: 'Switch the readout to sensor-centred metric coordinates. The continuous projection (x, y) = (fX/Z, fY/Z) is unchanged, but it is now measured from the principal point on the physical sensor.', s: { f: 3.2, w: 3.0, N: 16, mode: 1 } },
  { t: 'Sampling into pixels', n: 'Raise the resolution to 32 columns: pixel size s_x = w/N halves, the snapped cell hugs the continuous point, and the pixel indices n, m show the principal point offset (ox, oy) explicitly.', s: { f: 3.2, w: 3.0, N: 32, mode: 2 } }
];
let stepI = 0, tween = null, playing = false, playT = null;
function goToStep(i) {
  stepI = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepI];
  document.getElementById('stepTitle').textContent = (stepI + 1) + '. ' + st.t;
  document.getElementById('stepText').textContent = st.n;
  setMode(st.s.mode);
  tween = { from: { f: S.f, w: S.w, N: S.N }, to: st.s, t0: performance.now(), dur: 520 };
}
document.getElementById('btnPrev').addEventListener('click', () => { playing = false; clearInterval(playT); document.getElementById('btnPlay').classList.remove('active'); goToStep(stepI - 1); });
document.getElementById('btnNext').addEventListener('click', () => { playing = false; clearInterval(playT); document.getElementById('btnPlay').classList.remove('active'); goToStep(stepI + 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  playing = !playing;
  e.target.classList.toggle('active', playing);
  clearInterval(playT);
  if (playing) { goToStep(stepI + 1); playT = setInterval(() => goToStep(stepI + 1), 3800); }
});

function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const u = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
    S.f = tween.from.f + (tween.to.f - tween.from.f) * e;
    S.w = tween.from.w + (tween.to.w - tween.from.w) * e;
    S.N = tween.from.N + (tween.to.N - tween.from.N) * e;
    elF.value = S.f; elW.value = S.w; elN.value = Math.round(S.N);
    syncSliderText(); rebuildAll();
    if (u >= 1) tween = null;
  }
}
tick();

syncSliderText();
goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

