}
function mkDArrow(a, b, r, mat, order, headLen, headR) {
  const g = new THREE.Group();
  g.add(mkArrow(a, b, r, mat, order, headLen, headR));
  g.add(mkArrow(b, a, r, mat, order, headLen, headR));
  return g;
}
function mkDot(p, r, mat, order, outline) {
  const g = new THREE.Group();
  if (outline) { const o = new THREE.Mesh(SPHG, M_OUT); o.scale.setScalar(r * 1.38); o.renderOrder = (order || 13); g.add(o); }
  const m = new THREE.Mesh(SPHG, mat); m.scale.setScalar(r); m.renderOrder = (order || 13) + 1;
  g.add(m); g.position.copy(p);
  return g;
}
function mkQuad(wid, hei, mat, order) {
  const m = new THREE.Mesh(PLNG, mat); m.scale.set(wid, hei, 1); m.renderOrder = order || 5; return m;
}
function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.traverse(o => { if (o.geometry && o.geometry.userData && o.geometry.userData.own) o.geometry.dispose(); });
    g.remove(c);
  }
}

/* ---------- state ---------- */
const SCENE_Z = 6.5;
const SC = { x: -0.45, y: 0.35 };                      // scene-plane centre (camera coords)
const S = { f: 2, w: 2.4, N: 16, P: new THREE.Vector3(-1.5, 0.95, SCENE_Z), mode: 0 };

/* ---------- the pictured scene (green field, yellow windows, red roof) ---------- */
const ROOF = [[-1.8, 0.6], [0.2, 2.6], [1.8, 2.6], [1.8, 1.0]];
const WIN  = [[-0.75, 0.55], [0.75, 0.55], [-0.75, -0.6], [0.75, -0.6]];
const C_RED = [0.933, 0.126, 0.153], C_YEL = [0.949, 0.760, 0.118], C_GRN = [0.663, 0.910, 0.627];
function inRoof(x, y) {
  let s = 0;
  for (let i = 0; i < 4; i++) {
    const a = ROOF[i], b = ROOF[(i + 1) % 4];
    const c = (b[0] - a[0]) * (y - a[1]) - (b[1] - a[1]) * (x - a[0]);
    if (c > 0) s++; else if (c < 0) s--;
  }
