}
function picColor(lx, ly) {                      // local scene-plane coords
  if (inRoof(lx, ly)) return C_RED;
  if (Math.abs(lx) <= 1.8 && Math.abs(ly) <= 1.5) {
    for (const c of WIN) if (Math.abs(lx - c[0]) <= 0.35 && Math.abs(ly - c[1]) <= 0.35) return C_YEL;
    return C_GRN;
  }
