}

/* ---------- groups ---------- */
const gStatic = new THREE.Group(); scene.add(gStatic);
const gDyn    = new THREE.Group(); scene.add(gDyn);
const gRay    = new THREE.Group(); scene.add(gRay);

/* ---------- static: scene object, Yc, Xc, camera center ---------- */
(function buildStatic() {
  const plane = mkQuad(3.6, 3.0, M_SGREEN, 7);
  plane.position.set(SC.x, SC.y, SCENE_Z);
  gStatic.add(plane);
