    title: 'Scene plane', tooltip: 'The 3-D object being imaged',
    body: 'A planar object standing in the world at Z = 6.5. Every point on it is projected through the camera centre onto the image planes; the physical sensor receives the 180°-rotated (inverted) copy.'
  });
  for (const c of WIN) { const q = mkQuad(0.7, 0.7, M_YEL, 8); q.position.set(SC.x + c[0], SC.y + c[1], SCENE_Z); gStatic.add(q); }

  const rg = new THREE.BufferGeometry();
  const pos = [];
  for (const k of [0, 1, 2, 0, 2, 3]) pos.push(SC.x + ROOF[k][0], SC.y + ROOF[k][1], SCENE_Z);
  rg.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  rg.userData.own = true;
  const roof = new THREE.Mesh(rg, M_RED); roof.renderOrder = 9; gStatic.add(roof);

  // Yc axis (vertical)
  gStatic.add(mkArrow(new THREE.Vector3(0, -2.6, 0), new THREE.Vector3(0, 3.3, 0), 0.028, M_BLACK, 10));
  // Xc axis (receding depth direction)
