  const xs = -xv, ys = -yv;
  const nc = xs / sx + ox, mc = oy - ys / sy;
  const ni = Math.floor(nc), mi = Math.floor(mc);
  if (ni >= 0 && ni < N && mi >= 0 && mi < M) {
    hlQuad.visible = true;
    hlQuad.scale.set(sx, sy, 1);
    hlQuad.position.set(x0 + (ni + 0.5) * sx, yTop - (mi + 0.5) * sy, -f);
  } else hlQuad.visible = false;

  updateReadout(xv, yv, nc, mc, ni, mi);
}

function fmt(v, dd) { dd = (dd === undefined ? 2 : dd); return (Math.abs(v) < 5e-4 ? 0 : v).toFixed(dd); }
function updateReadout(xv, yv, nc, mc, ni, mi) {
  const { sx, sy, ox, oy, w, h } = SEN, f = S.f, P = S.P;
  const fx = f / sx, fy = f / sy;
  let txt = 'P (camera) = (' + fmt(P.x) + ', ' + fmt(P.y) + ', ' + fmt(P.z) + ')\n';
  if (S.mode === 0) {
    txt += 'x = f·X/Z = ' + fmt(xv, 3) + '\n';
    txt += 'y = f·Y/Z = ' + fmt(yv, 3) + '\n';
    txt += '(virtual plane, upright)';
  } else if (S.mode === 1) {
    txt += 'sensor hit from principal pt:\n';
    txt += '  xs = −x = ' + fmt(-xv * 10, 2) + ' mm\n';
    txt += '  ys = −y = ' + fmt(-yv * 10, 2) + ' mm\n';
    txt += 'sensor ' + fmt(w * 10, 1) + ' × ' + fmt(h * 10, 1) + ' mm\n';
    txt += 'pixel ' + fmt(sx * 10, 3) + ' × ' + fmt(sy * 10, 3) + ' mm';
  } else {
    txt += 'n = xs/s_x + ox = ' + fmt(nc) + '\n';
    txt += 'm = oy − ys/s_y = ' + fmt(mc) + '\n';
    txt += 'snapped (n, m) = (' + ni + ', ' + mi + ')\n';
    txt += 'principal pt (ox, oy) = (' + fmt(ox, 1) + ', ' + fmt(oy, 1) + ')';
  }
  txt += '\n\nK = [' + fmt(fx, 1).padStart(6) + '    0  ' + fmt(ox, 1).padStart(5) + ' ]\n';
  txt += '    [    0  ' + fmt(fy, 1).padStart(6) + '  ' + fmt(oy, 1).padStart(5) + ' ]\n';
  txt += '    [    0       0    1.0 ]';
  document.getElementById('readout').textContent = txt;
}

/* ---------- labels (created before the first layout() that uses them) ------ */
function lab(html, opts) {
  opts = opts || {};
  const e = addLabel(html, new THREE.Vector3(), opts);
  e.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  if (opts.rot) e.div.innerHTML = '<span style="display:inline-block;transform:rotate(' + opts.rot + 'deg)">' + html + '</span>';
  return e;
}
L.imgplane = lab('Image plane / sensor', { fontSize: '15px' });
L.npx      = lab('<i>N</i> pixels', { fontSize: '14px', rot: -40 });
L.mpx      = lab('<i>M</i> pixels', { fontSize: '14px', rot: -72 });
L.w        = lab('<i>w</i>', { fontSize: '17px' });
L.f        = lab('<i>f</i>', { fontSize: '18px' });
L.vplane   = lab('Virtual image plane', { fontSize: '14px', rot: -40 });
L.xg       = lab('<i>x</i>', { fontSize: '18px', color: '#0f9b0f' });
L.yg       = lab('<i>y</i>', { fontSize: '18px', color: '#0f9b0f' });
L.P        = lab('<b>P</b>', { fontSize: '18px' });
L.cc       = lab('Camera<br>center', { fontSize: '15px' });
L.opt      = lab('Optical /<br>principal axis', { fontSize: '15px' });
L.Xc       = lab('X<sub>c</sub>', { fontSize: '20px' });
L.Yc       = lab('Y<sub>c</sub>', { fontSize: '20px' });
L.Zc       = lab('Z<sub>c</sub>', { fontSize: '20px' });
L.cc.pos.set(0, -1.55, -1.25);
L.opt.pos.set(0, 1.25, 7.9);
L.Xc.pos.set(2.6, 0.2, 0);  L.Xc.offset = [-2, -16];
L.Yc.pos.set(0, 3.45, 0);   L.Yc.offset = [22, -4];
L.Zc.pos.set(0, -0.5, 8.7);

function layout() {
  if (!L.f || !SEN.w) return;
  const w = SEN.w, h = SEN.h, f = SEN.f, z = -f;
  L.imgplane.pos.set(SEN.x0 + w * 0.15, SEN.yTop + 0.8, z);
  L.npx.pos.set(SEN.x0 + w * 0.28, SEN.yTop + 0.2, z);
  L.mpx.pos.set(SEN.x0 - 0.2, SEN.y0 + h * 0.35, z);
  L.w.pos.set(-0.1, SEN.fY + 0.34, z); L.w.offset = [-16, 0];
  L.f.pos.set(0, SEN.fY - 0.36, -f / 2);
  L.vplane.pos.set(-w * 0.26, -h * 0.5 - 0.16, f);
  L.xg.pos.copy(SEN.ax1).add(new THREE.Vector3(0.12, 0.18, 0));
  L.yg.pos.copy(SEN.ay1).add(new THREE.Vector3(-0.2, 0.14, 0));
