/* ---------- first build & camera (orthographic axonometric, Zc → screen right) */
rebuildAll();
setCameraView({ projection: 'orthographic', azimuthDeg: 160, elevationDeg: 18, rollDeg: 0, heightFraction: 0.8 });
layout();

const bReset = document.getElementById('btnReset');
bReset.style.display = ''; bReset.textContent = 'Reset view';

/* ---------- drag P ---------- */
const dragRC = new THREE.Raycaster();
const dragPt = new THREE.Vector2();
const dragPlane = new THREE.Plane();
const hitV = new THREE.Vector3();
let dragging = false;
function setPtr(e) {
  const r = canvas.getBoundingClientRect();
  dragPt.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  dragPt.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
window.addEventListener('pointerdown', (e) => {
  if (e.target !== canvas) return;
  setPtr(e); dragRC.setFromCamera(dragPt, camera);
  if (dragRC.intersectObject(pHit, false).length) {
    dragging = true; controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    e.stopPropagation(); e.preventDefault();
  }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setPtr(e); dragRC.setFromCamera(dragPt, camera);
  const depthMode = document.getElementById('chkZ').checked;
  if (depthMode) dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 1, 0), S.P);
  else dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 0, 1), S.P);
