    if (depthMode) S.P.z = THREE.MathUtils.clamp(hitV.z, 3, 9);
    else {
      S.P.x = THREE.MathUtils.clamp(hitV.x, SC.x - 1.8, SC.x + 1.8);
      S.P.y = THREE.MathUtils.clamp(hitV.y, SC.y - 1.5, SC.y + 1.5);
    }
