  }
  e.preventDefault();
}, true);
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'default'; }
});

/* ---------- UI wiring ---------- */
const elF = document.getElementById('sF'), elW = document.getElementById('sW'), elN = document.getElementById('sN');
function syncSliderText() {
  document.getElementById('vF').textContent = S.f.toFixed(2);
  document.getElementById('vW').textContent = S.w.toFixed(2);
  document.getElementById('vN').textContent = Math.round(S.N);
  document.getElementById('vM').textContent = Math.max(3, Math.round(Math.round(S.N) * 0.75));
}
elF.addEventListener('input', () => { tween = null; S.f = parseFloat(elF.value); syncSliderText(); rebuildAll(); });
elW.addEventListener('input', () => { tween = null; S.w = parseFloat(elW.value); syncSliderText(); rebuildAll(); });
elN.addEventListener('input', () => { tween = null; S.N = parseFloat(elN.value); syncSliderText(); rebuildAll(); });

function setMode(i) {
  S.mode = i;
  for (let k = 0; k < 3; k++) document.getElementById('rm' + k).classList.toggle('active', k === i);
  updateProjection();
}
for (let k = 0; k < 3; k++) document.getElementById('rm' + k).addEventListener('click', () => setMode(k));

/* ---------- demo steps ---------- */
const STEPS = [
  { t: 'The pinhole ray', n: 'A single dashed ray leaves scene point P, passes exactly through the camera center, and strikes the sensor behind it. Where it crosses the virtual image plane at distance f is the upright image; on the real sensor the same ray lands inverted.', s: { f: 2, w: 2.4, N: 16, mode: 0 } },
  { t: 'Longer focal length', n: 'Pushing f out to 3.2 moves both image planes away from the pinhole. The projected point swings further from the optical axis and the field of view narrows — the classic zoom-in tradeoff.', s: { f: 3.2, w: 2.4, N: 16, mode: 0 } },
  { t: 'Sensor-centred millimetres', n: 'Switch the readout to sensor-centred metric coordinates. The continuous projection (x, y) = (fX/Z, fY/Z) is unchanged, but it is now measured from the principal point on the physical sensor.', s: { f: 3.2, w: 3.0, N: 16, mode: 1 } },
  { t: 'Sampling into pixels', n: 'Raise the resolution to 32 columns: pixel size s_x = w/N halves, the snapped cell hugs the continuous point, and the indices n = x/s_x + ox, m = oy − y/s_y show the principal-point offset explicitly.', s: { f: 3.2, w: 3.0, N: 32, mode: 2 } }
];
let stepI = 0, tween = null, playing = false, playT = null;
function goToStep(i) {
  stepI = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepI];
  document.getElementById('stepTitle').textContent = (stepI + 1) + '. ' + st.t;
  document.getElementById('stepText').textContent = st.n;
  setMode(st.s.mode);
  tween = { from: { f: S.f, w: S.w, N: S.N }, to: st.s, t0: performance.now(), dur: 520 };
}
function stopPlay() { playing = false; clearInterval(playT); document.getElementById('btnPlay').classList.remove('active'); }
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepI - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepI + 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  playing = !playing;
  e.target.classList.toggle('active', playing);
  clearInterval(playT);
  if (playing) { goToStep(stepI + 1); playT = setInterval(() => goToStep(stepI + 1), 4200); }
});

function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const u = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
    S.f = tween.from.f + (tween.to.f - tween.from.f) * e;
    S.w = tween.from.w + (tween.to.w - tween.from.w) * e;
    S.N = tween.from.N + (tween.to.N - tween.from.N) * e;
    elF.value = S.f; elW.value = S.w; elN.value = Math.round(S.N);
    syncSliderText(); rebuildAll();
    if (u >= 1) tween = null;
  }
}
tick();

syncSliderText();
goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

