  // Yc axis (vertical)
  gStatic.add(mkArrow(new THREE.Vector3(0, -2.8, 0), new THREE.Vector3(0, 3.1, 0), 0.034, M_BLACK, 10));
  // Xc axis (receding depth direction)
  gStatic.add(mkArrow(new THREE.Vector3(0, 0, 0), new THREE.Vector3(2.2, 0, 0), 0.034, M_BLACK, 10));
  // camera centre + gray leader arrow toward the 'Camera center' text
  const cc = mkDot(new THREE.Vector3(0, 0, 0), 0.115, M_BLACK, 11, false);
  gStatic.add(cc);
  registerInteractive(cc, {
    title: 'Camera centre (pinhole)', tooltip: 'Origin of the camera frame',
    body: 'All projection rays pass through this single point. It is the origin of the camera coordinate frame (Xc, Yc, Zc); the optical axis is Zc.'
  });
  gStatic.add(mkArrow(new THREE.Vector3(0, -1.30, -1.05), new THREE.Vector3(-0.02, -0.22, -0.15), 0.016, M_GRAY, 10, 0.18, 0.055));
})();

/* ---------- point P + invisible drag handle ---------- */
const gP  = mkDot(S.P, 0.105, M_CYAN, 14, true); gRay.add(gP);
const pHit = new THREE.Mesh(SPHG, M_HIT); pHit.scale.setScalar(0.34); pHit.position.copy(S.P); gRay.add(pHit);
const gPv = mkDot(new THREE.Vector3(), 0.095, M_CYAN, 14, true); gRay.add(gPv);
const gPs = mkDot(new THREE.Vector3(), 0.095, M_CYAN, 14, true); gRay.add(gPs);
registerInteractive(pHit, {
  title: 'Scene point P', tooltip: 'Drag me across the scene plane',
  body: 'P is a 3-D point in camera coordinates (X, Y, Z). Its image is x = f·X/Z, y = f·Y/Z on the virtual plane, and (−x, −y) on the physical sensor — the same ray, one pinhole.'
});

/* ---------- dash pool for the projection ray ---------- */
const DASH_MAX = 180, dashPool = [];
for (let i = 0; i < DASH_MAX; i++) {
  const m = new THREE.Mesh(CYLG, M_BLACK); m.visible = false; m.renderOrder = 12; gRay.add(m); dashPool.push(m);
}
function drawDash(a, b, r, ds, gs) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length(); dir.normalize();
  let t = 0, i = 0;
  while (t < len && i < DASH_MAX) {
    const e = Math.min(t + ds, len);
    placeCyl(dashPool[i], a.clone().addScaledVector(dir, t), a.clone().addScaledVector(dir, e), r);
    dashPool[i].visible = true; i++; t = e + gs;
  }
  for (; i < DASH_MAX; i++) dashPool[i].visible = false;
}

/* ---------- highlight quad (snapped pixel) ---------- */
const hlQuad = mkQuad(0.1, 0.1, M_HL, 3); gRay.add(hlQuad);

/* ---------- dynamic build: sensor, virtual plane, Zc axis, dimensions ---------- */
function rebuildAll() {
  clearGroup(gDyn);
  const w = S.w, h = 0.75 * S.w, f = S.f;
  const N = Math.max(3, Math.round(S.N)), M = Math.max(3, Math.round(N * 0.75));
  const sx = w / N, sy = h / M;
  const ox = N / 2 + 1.5, oy = M / 2 - 1.0;          // principal point in cell units
  const x0 = -ox * sx, yTop = oy * sy, y0 = yTop - h;
  SEN = { w, h, f, N, M, sx, sy, ox, oy, x0, yTop, y0 };
  const zs = -f;

  /* sensor pixels: inverted image of the scene */
  const vpos = [], vcol = [];
  for (let i = 0; i < N; i++) for (let j = 0; j < M; j++) {
    const cx = x0 + (i + 0.5) * sx, cy = yTop - (j + 0.5) * sy;
    const c = picColor(-cx * SCENE_Z / f - SC.x, -cy * SCENE_Z / f - SC.y);
    if (!c) continue;
    const ax = x0 + i * sx, bx = ax + sx, by = yTop - j * sy, ay = by - sy;
    vpos.push(ax, ay, zs, bx, ay, zs, bx, by, zs, ax, ay, zs, bx, by, zs, ax, by, zs);
    for (let k = 0; k < 6; k++) vcol.push(c[0], c[1], c[2]);
  }
  if (vpos.length) {
    const pg = new THREE.BufferGeometry();
    pg.setAttribute('position', new THREE.Float32BufferAttribute(vpos, 3));
    pg.setAttribute('color', new THREE.Float32BufferAttribute(vcol, 3));
    pg.userData.own = true;
    const pm = new THREE.Mesh(pg, M_PIX); pm.renderOrder = 1; gDyn.add(pm);
  }

  /* sensor grid lines */
  const lp = [];
  for (let i = 0; i <= N; i++) { const x = x0 + i * sx; lp.push(x, y0, zs, x, yTop, zs); }
  for (let j = 0; j <= M; j++) { const y = yTop - j * sy; lp.push(x0, y, zs, x0 + w, y, zs); }
  const lg = new THREE.BufferGeometry();
  lg.setAttribute('position', new THREE.Float32BufferAttribute(lp, 3));
  lg.userData.own = true;
  const grid = new THREE.LineSegments(lg, M_GRID); grid.renderOrder = 2; gDyn.add(grid);
  registerInteractive(grid, {
    title: 'Image plane / sensor', tooltip: 'M × N discrete pixels at z = −f',
    body: 'The physical sensor sits a distance f BEHIND the pinhole, so the image on it is inverted. Its surface is sampled by M × N pixels of size s_x = w/N, s_y = h/M — that sampling is what turns continuous (x, y) into integer indices (n, m).'
  });

  /* principal point on the sensor */
  gDyn.add(mkDot(new THREE.Vector3(0, 0, zs), 0.06, M_BLACK, 11, false));

  /* w tick + f dimension */
  const fY = y0 - 0.9;
  gDyn.add(mkCyl(new THREE.Vector3(0, y0, zs), new THREE.Vector3(0, fY, zs), 0.013, M_BLACK, 11));
  gDyn.add(mkDArrow(new THREE.Vector3(0, fY, zs), new THREE.Vector3(0, fY, 0), 0.022, M_BLACK, 11, 0.26, 0.08));

  /* Zc / optical axis */
  gDyn.add(mkArrow(new THREE.Vector3(0, 0, zs - 0.5), new THREE.Vector3(0, 0, 7.5), 0.036, M_BLACK, 10, 0.36, 0.115));

  /* virtual image plane */
  const vp = mkQuad(w, h, M_VP, 4); vp.position.set(0, 0, f); gDyn.add(vp);
  registerInteractive(vp, {
    title: 'Virtual image plane', tooltip: 'Upright image at z = +f',
    body: 'A mathematically convenient copy of the sensor placed a distance f IN FRONT of the pinhole. The image here is upright and obeys x = f·X/Z, y = f·Y/Z; the real sensor sees exactly (−x, −y).'
  });
  const c1 = new THREE.Vector3(-w / 2, -h / 2, f), c2 = new THREE.Vector3(w / 2, -h / 2, f),
        c3 = new THREE.Vector3(w / 2, h / 2, f), c4 = new THREE.Vector3(-w / 2, h / 2, f);
  [[c1, c2], [c2, c3], [c3, c4], [c4, c1]].forEach(e => gDyn.add(mkCyl(e[0], e[1], 0.036, M_DGRAY, 5)));

  /* local green image axes on the virtual plane */
  const ax0 = new THREE.Vector3(-0.42 * w, 0, f), ax1 = new THREE.Vector3(0.30 * w, 0, f);
  const ay0 = new THREE.Vector3(0, -0.40 * h, f), ay1 = new THREE.Vector3(0, 0.46 * h, f);
  gDyn.add(mkArrow(ax0, ax1, 0.026, M_GRN, 6, 0.26, 0.085));
  gDyn.add(mkArrow(ay0, ay1, 0.026, M_GRN, 6, 0.26, 0.085));
  const a = 0.22;
  gDyn.add(mkCyl(new THREE.Vector3(a, 0, f), new THREE.Vector3(a, a, f), 0.016, M_GRN, 6));
  gDyn.add(mkCyl(new THREE.Vector3(0, a, f), new THREE.Vector3(a, a, f), 0.016, M_GRN, 6));

  SEN.fY = fY; SEN.ax1 = ax1; SEN.ay1 = ay1;
  layout();
  updateProjection();
}

/* ---------- projection + readout ---------- */
function updateProjection() {
  const f = S.f, P = S.P;
  const Z = Math.max(P.z, 0.25);
  const xv = f * P.x / Z, yv = f * P.y / Z;
  gP.position.copy(P); pHit.position.copy(P);
  gPv.position.set(xv, yv, f);
  gPs.position.set(-xv, -yv, -f);
  drawDash(P, gPs.position, 0.024, 0.13, 0.085);

  const { sx, sy, x0, yTop, N, M, ox, oy } = SEN;
  const xs = -xv, ys = -yv;
  const nc = xs / sx + ox, mc = oy - ys / sy;
  const ni = Math.floor(nc), mi = Math.floor(mc);
  if (ni >= 0 && ni < N && mi >= 0 && mi < M) {
    hlQuad.visible = true;
    hlQuad.scale.set(sx, sy, 1);
    hlQuad.position.set(x0 + (ni + 0.5) * sx, yTop - (mi + 0.5) * sy, -f);
  } else hlQuad.visible = false;

  updateReadout(xv, yv, nc, mc, ni, mi);
}

function fmt(v, dd) { dd = (dd === undefined ? 2 : dd); return (Math.abs(v) < 5e-4 ? 0 : v).toFixed(dd); }
function updateReadout(xv, yv, nc, mc, ni, mi) {
  const { sx, sy, ox, oy, w, h } = SEN, f = S.f, P = S.P;
  const fx = f / sx, fy = f / sy;
  let txt = 'P (camera) = (' + fmt(P.x) + ', ' + fmt(P.y) + ', ' + fmt(P.z) + ')\n';
  if (S.mode === 0) {
    txt += 'x = f·X/Z = ' + fmt(xv, 3) + '\n';
    txt += 'y = f·Y/Z = ' + fmt(yv, 3) + '\n';
    txt += '(virtual plane, upright)';
  } else if (S.mode === 1) {
    txt += 'sensor hit from principal pt:\n';
    txt += '  xs = −x = ' + fmt(-xv * 10, 2) + ' mm\n';
    txt += '  ys = −y = ' + fmt(-yv * 10, 2) + ' mm\n';
    txt += 'sensor ' + fmt(w * 10, 1) + ' × ' + fmt(h * 10, 1) + ' mm\n';
    txt += 'pixel ' + fmt(sx * 10, 3) + ' × ' + fmt(sy * 10, 3) + ' mm';
  } else {
    txt += 'n = xs/s_x + ox = ' + fmt(nc) + '\n';
    txt += 'm = oy − ys/s_y = ' + fmt(mc) + '\n';
    txt += 'snapped (n, m) = (' + ni + ', ' + mi + ')\n';
    txt += 'principal pt (ox, oy) = (' + fmt(ox, 1) + ', ' + fmt(oy, 1) + ')';
  }
  txt += '\n\nK = [' + fmt(fx, 1).padStart(6) + '    0  ' + fmt(ox, 1).padStart(5) + ' ]\n';
  txt += '    [    0  ' + fmt(fy, 1).padStart(6) + '  ' + fmt(oy, 1).padStart(5) + ' ]\n';
  txt += '    [    0       0    1.0 ]';
  document.getElementById('readout').textContent = txt;
}

/* ---------- labels (created before the first layout() that uses them) ------ */
function lab(html, opts) {
  opts = opts || {};
  const e = addLabel(html, new THREE.Vector3(), opts);
  e.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  if (opts.rot) e.div.innerHTML = '<span style="display:inline-block;transform:rotate(' + opts.rot + 'deg)">' + html + '</span>';
  return e;
}
L.imgplane = lab('Image plane / sensor', { fontSize: '16px' });
L.npx      = lab('<i>N</i> pixels', { fontSize: '15px', rot: -40 });
L.mpx      = lab('<i>M</i> pixels', { fontSize: '15px', rot: -90 });
L.w        = lab('<i>w</i>', { fontSize: '18px' });
L.f        = lab('<i>f</i>', { fontSize: '19px' });
L.vplane   = lab('Virtual image plane', { fontSize: '15px', rot: -40 });
L.xg       = lab('<i>x</i>', { fontSize: '19px', color: '#0f9b0f' });
L.yg       = lab('<i>y</i>', { fontSize: '19px', color: '#0f9b0f' });
L.P        = lab('<b>P</b>', { fontSize: '19px' });
L.cc       = lab('Camera<br>center', { fontSize: '16px' });
L.opt      = lab('Optical /<br>principal axis', { fontSize: '16px' });
L.Xc       = lab('X<sub>c</sub>', { fontSize: '21px' });
L.Yc       = lab('Y<sub>c</sub>', { fontSize: '21px' });
L.Zc       = lab('Z<sub>c</sub>', { fontSize: '21px' });
L.cc.pos.set(0, -1.72, -1.30);
L.opt.pos.set(0, 1.35, 6.8);
L.Xc.pos.set(2.30, 0.18, 0);  L.Xc.offset = [-4, -16];
L.Yc.pos.set(0, 3.25, 0);     L.Yc.offset = [22, -4];
L.Zc.pos.set(0, -0.55, 7.25);

function layout() {
  if (!L.f || !SEN.w) return;
  const w = SEN.w, h = SEN.h, f = SEN.f, z = -f;
  // 'Image plane / sensor' well above the grid's top edge
  L.imgplane.pos.set(SEN.x0 - 0.05, SEN.yTop + 1.05, z);
  // 'N pixels' hugging the OUTSIDE of the top edge (column direction = +X)
  L.npx.pos.set(SEN.x0 + w * 0.34, SEN.yTop + 0.20, z);
  L.npx.offset = [-10, -12];
  // 'M pixels' hugging the OUTSIDE of the left edge (row direction = −Y)
  L.mpx.pos.set(SEN.x0 - 0.06, SEN.y0 + h * 0.45, z);
  L.mpx.offset = [-16, 0];
  L.w.pos.set(0, (SEN.y0 + SEN.fY) * 0.5, z); L.w.offset = [-16, 0];
  L.f.pos.set(0, SEN.fY - 0.38, -f / 2);
  L.vplane.pos.set(-w * 0.27, -h * 0.5 - 0.20, f);
  L.xg.pos.copy(SEN.ax1).add(new THREE.Vector3(0.14, 0.20, 0));
  L.yg.pos.copy(SEN.ay1).add(new THREE.Vector3(-0.22, 0.16, 0));
  L.P.pos.copy(S.P).add(new THREE.Vector3(0, 0.34, 0)); L.P.offset = [-14, -6];
}

/* ---------- first build & camera (orthographic axonometric, Zc → screen right) */
rebuildAll();
setCameraView({ projection: 'orthographic', azimuthDeg: 160, elevationDeg: 18, rollDeg: 0, heightFraction: 0.86 });
layout();

const bReset = document.getElementById('btnReset');
bReset.style.display = ''; bReset.textContent = 'Reset view';

/* ---------- drag P ---------- */
const dragRC = new THREE.Raycaster();
const dragPt = new THREE.Vector2();
const dragPlane = new THREE.Plane();
const hitV = new THREE.Vector3();
let dragging = false;
function setPtr(e) {
  const r = canvas.getBoundingClientRect();
  dragPt.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  dragPt.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
window.addEventListener('pointerdown', (e) => {
  if (e.target !== canvas) return;
  setPtr(e); dragRC.setFromCamera(dragPt, camera);
  if (dragRC.intersectObject(pHit, false).length) {
    dragging = true; controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    e.stopPropagation(); e.preventDefault();
  }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setPtr(e); dragRC.setFromCamera(dragPt, camera);
  const depthMode = document.getElementById('chkZ').checked;
  if (depthMode) dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 1, 0), S.P);
  else dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 0, 1), S.P);
  if (dragRC.ray.intersectPlane(dragPlane, hitV)) {
    if (depthMode) S.P.z = THREE.MathUtils.clamp(hitV.z, 3, 9);
    else {
      S.P.x = THREE.MathUtils.clamp(hitV.x, SC.x - SW, SC.x + SW);
      S.P.y = THREE.MathUtils.clamp(hitV.y, SC.y - SH, SC.y + SH);
    }
    layout(); updateProjection();
  }
  e.preventDefault();
}, true);
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'default'; }
});

/* ---------- UI wiring ---------- */
const elF = document.getElementById('sF'), elW = document.getElementById('sW'), elN = document.getElementById('sN');
function syncSliderText() {
  document.getElementById('vF').textContent = S.f.toFixed(2);
  document.getElementById('vW').textContent = S.w.toFixed(2);
  document.getElementById('vN').textContent = Math.round(S.N);
  document.getElementById('vM').textContent = Math.max(3, Math.round(Math.round(S.N) * 0.75));
}
elF.addEventListener('input', () => { tween = null; S.f = parseFloat(elF.value); syncSliderText(); rebuildAll(); });
elW.addEventListener('input', () => { tween = null; S.w = parseFloat(elW.value); syncSliderText(); rebuildAll(); });
elN.addEventListener('input', () => { tween = null; S.N = parseFloat(elN.value); syncSliderText(); rebuildAll(); });

function setMode(i) {
  S.mode = i;
  for (let k = 0; k < 3; k++) document.getElementById('rm' + k).classList.toggle('active', k === i);
  updateProjection();
}
for (let k = 0; k < 3; k++) document.getElementById('rm' + k).addEventListener('click', () => setMode(k));

/* ---------- demo steps ---------- */
const STEPS = [
  { t: 'The pinhole ray', n: 'A single dashed ray leaves scene point P, passes exactly through the camera center, and strikes the sensor behind it. Where it crosses the virtual image plane at distance f is the upright image; on the real sensor the same ray lands inverted.', s: { f: 2, w: 3.8, N: 16, mode: 0 } },
  { t: 'Longer focal length', n: 'Pushing f out to 3.2 moves both image planes away from the pinhole. The projected point swings further from the optical axis and the image of the scene grows on the sensor — the classic zoom-in tradeoff.', s: { f: 3.2, w: 3.8, N: 16, mode: 0 } },
  { t: 'Sensor-centred millimetres', n: 'Switch the readout to sensor-centred metric coordinates. The continuous projection (x, y) = (fX/Z, fY/Z) is unchanged, but it is now measured from the principal point on the physical sensor.', s: { f: 3.2, w: 4.6, N: 16, mode: 1 } },
  { t: 'Sampling into pixels', n: 'Raise the resolution to 32 columns: pixel size s_x = w/N halves, the snapped cell hugs the continuous point, and the indices n = x/s_x + ox, m = oy − y/s_y show the principal-point offset explicitly.', s: { f: 3.2, w: 4.6, N: 32, mode: 2 } }
];
let stepI = 0, tween = null, playing = false, playT = null;
function goToStep(i) {
  stepI = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepI];
  document.getElementById('stepTitle').textContent = (stepI + 1) + '. ' + st.t;
  document.getElementById('stepText').textContent = st.n;
  setMode(st.s.mode);
  tween = { from: { f: S.f, w: S.w, N: S.N }, to: st.s, t0: performance.now(), dur: 520 };
}
function stopPlay() { playing = false; clearInterval(playT); document.getElementById('btnPlay').classList.remove('active'); }
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepI - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepI + 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  playing = !playing;
  e.target.classList.toggle('active', playing);
  clearInterval(playT);
  if (playing) { goToStep(stepI + 1); playT = setInterval(() => goToStep(stepI + 1), 4200); }
});

function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const u = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
    S.f = tween.from.f + (tween.to.f - tween.from.f) * e;
    S.w = tween.from.w + (tween.to.w - tween.from.w) * e;
    S.N = tween.from.N + (tween.to.N - tween.from.N) * e;
    elF.value = S.f; elW.value = S.w; elN.value = Math.round(S.N);
    syncSliderText(); rebuildAll();
    if (u >= 1) tween = null;
  }
}
tick();

syncSliderText();
goToStep(0);
